import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double for the pricing downstream (priceOf(sku) -> euros).
const prices = { A: 10, B: 25, C: 10.5, D: 101, E: 100 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const create = async (items) => { const r = await post({ items }); return { r, body: await r.json() } }

test('POST /orders 201 returns order with string id, echoed items and total', async () => {
  const items = [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }]
  const { r, body } = await create(items)
  assert.equal(r.status, 201)
  assert.equal(r.headers.get('content-type'), 'application/json')
  assert.match(body.id, /^\d+$/)
  assert.deepEqual(body.items, items)
  assert.equal(body.total, 45)
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.ok(calls.includes('A') && calls.includes('B'))
})

test('POST /orders ids are sequential strings', async () => {
  const a = await create([{ sku: 'A', qty: 1 }])
  const b = await create([{ sku: 'A', qty: 1 }])
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('POST /orders total of exactly 100 gets no discount', async () => {
  assert.equal((await create([{ sku: 'E', qty: 1 }])).body.total, 100)
})

test('POST /orders total above 100 gets 10% discount', async () => {
  assert.equal((await create([{ sku: 'A', qty: 11 }])).body.total, 99)
})

test('POST /orders total is floored, not rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — fractional euros truncated (10.5 -> 10; 101 less 10% = 90.9 -> 90)
  assert.equal((await create([{ sku: 'C', qty: 1 }])).body.total, 10)
  assert.equal((await create([{ sku: 'D', qty: 1 }])).body.total, 90)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'A' }],
  ['empty body', undefined, ''],
  ['invalid JSON', undefined, '{nope'],
  ['JSON null', undefined, 'null'],
  ['JSON array', undefined, '[]'],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const r = await post(body, raw)
    assert.equal(r.status, 400)
    assert.equal(r.headers.get('content-type'), 'application/json')
    assert.deepEqual(await r.json(), { error: 'items required' })
  })
}

test('GET /orders/{id} returns the created order', async () => {
  const { body: created } = await create([{ sku: 'B', qty: 2 }])
  const r = await fetch(`${base}/orders/${created.id}`)
  assert.equal(r.status, 200)
  assert.equal(r.headers.get('content-type'), 'application/json')
  assert.deepEqual(await r.json(), created)
})

test('GET /orders/{id} unknown id answers 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — a missing order returns 200, not 404
  const r = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(r.status, 200)
  assert.deepEqual(await r.json(), { error: 'not found' })
})

for (const [method, path] of [
  ['GET', '/orders'], ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'],
  ['GET', '/orders/1/extra'], ['GET', '/'], ['GET', '/unknown'],
]) {
  test(`${method} ${path} -> 404 no route`, async () => {
    const r = await fetch(`${base}${path}`, { method })
    assert.equal(r.status, 404)
    assert.equal(r.headers.get('content-type'), 'application/json')
    assert.deepEqual(await r.json(), { error: 'no route' })
  })
}
